Please refactor this by using Array.reduce and removing Map constructor. `      const uniqueDataMap = new Map();

      this.data.map((item) =&gt; {
        if (!uniqueDataMap.has(item.company.id)) {
          uniqueDataMap.set(item.company.id, item);
          return true;
        }
        const otherItem = uniqueDataMap.get(item.company.id);
        uniqueDataMap.set(item.company.id, {
          ...item,
          startDate: this.$dayjs.min(
            this.$dayjs(otherItem.startDate),
            this.$dayjs(item.startDate),
          ),
          endDate: this.$dayjs.max(
            this.$dayjs(otherItem.endDate),
            this.$dayjs(item.endDate),
          ),
        });
        return false;
      });

      return [...uniqueDataMap.values()];`

